/* Load-time tables of the recompiled Mach-O image (generated by tools/lift.py into work/, never committed). */
#ifndef MACHO_TAB_H
#define MACHO_TAB_H
#include <stdint.h>
struct mo_seg { const char *name; uint32_t va, vsize, fileoff, filesize; int prot; };
struct mo_fix { uint32_t va, value; };                 /* write value at va (weak/self binds resolved at build time) */
struct mo_bind { uint32_t va; const char *name; int32_t addend; };   /* va = guest address of import `name` + addend */
extern const struct mo_seg mo_segs[]; extern const unsigned mo_segs_n;
extern const struct mo_fix mo_fixups[]; extern const unsigned mo_fixups_n;
extern const struct mo_bind mo_binds[]; extern const unsigned mo_binds_n;
extern const uint32_t mo_init[]; extern const unsigned mo_init_n;
extern const uint32_t mo_tlv[2];
extern const uint32_t mo_entry;
extern const char mo_dylibs[];
struct mo_unwind { uint32_t func, encoding, lsda; };   /* __unwind_info, sorted by function */
extern const struct mo_unwind mo_unwind[]; extern const unsigned mo_unwind_n;
extern const uint32_t mo_lazy[2], mo_tdata[4], mo_cfstring[2], mo_clsrefs[2];   /* __la_symbol_ptr, thread template, __cfstring: va, size */
#endif
